def rank_components(clean, corrupt, patched, threshold):
    if clean == corrupt:
        raise ValueError('clean and corrupted runs give the same metric')
    fracs = [(i, (p - corrupt) / (clean - corrupt)) for i, p in enumerate(patched)]
    kept = [(i, f) for i, f in fracs if f >= threshold - 1e-12]
    return sorted(kept, key=lambda t: -t[1])

